diagrams.mermaid:
flowchart TD
  Req["Principal calls an API"] --> Deny{"Matching deny policy rule?"}
  Deny -- "Yes, no exception" --> Blocked["Denied"]
  Deny -- "No" --> Allow{"Allow binding found on resource or ancestors, condition true?"}
  Allow -- "No" --> Blocked
  Allow -- "Yes" --> OrgP{"Org policy permits the resource configuration?"}
  OrgP -- "No" --> Blocked
  OrgP -- "Yes" --> Granted["Allowed"]
